use expanse_trie::sync::SyncExpanseStrMap;
use std::hint::black_box;
const POP: usize = 50_000;
fn tk(b: &[u8]) -> &expanse_trie::strmap::NulFreeStr {
    unsafe { expanse_trie::strmap::NulFreeStr::new_unchecked(b) }
}
struct XorShift(u64);
impl XorShift { fn next(&mut self) -> u64 { let mut x = self.0; x ^= x << 13; x ^= x >> 7; x ^= x << 17; self.0 = x; x } }
fn path_keys(dense: bool) -> Vec<Vec<u8>> {
    let mut rng = XorShift(0x5A71_C1A0_0000_0001);
    let mut seen = std::collections::HashSet::with_capacity(POP);
    let mut out = Vec::with_capacity(POP);
    while out.len() < POP {
        let r = rng.next();
        let id = if dense { let bucket = (r >> 28) % 52_428 * 20; (bucket << 28) | (r & 0xFFF_FFFF) } else { r & 0xFFFF_FFFF_FFFF };
        if seen.insert(id) { out.push(format!("https://example.com/api/v2/objects/{id:012x}").into_bytes()); }
    }
    out
}
#[inline(never)]
fn scan_locked(map: &SyncExpanseStrMap) -> u64 {
    let (mut n, mut sink) = (0u64, 0u64);
    map.with_locked(|m| { let mut cur = m.cursor(); while let Some((k, slot)) = cur.next() { sink ^= k.len() as u64 ^ unsafe { slot.as_ptr().read() }; n += 1; } });
    assert_eq!(n, POP as u64); sink
}
#[inline(never)]
fn scan_cursor(map: &SyncExpanseStrMap) -> u64 {
    let (mut n, mut sink) = (0u64, 0u64);
    { let rd = map.reader(); let mut cur = rd.cursor(); while let Some((k, v)) = cur.next() { sink ^= k.len() as u64 ^ v; n += 1; } }
    assert_eq!(n, POP as u64); sink
}
fn main() {
    let a: Vec<String> = std::env::args().collect();
    let dense = a[1] == "paths_dense";
    let map = SyncExpanseStrMap::new();
    for (i, k) in path_keys(dense).iter().enumerate() { map.insert(tk(k), i as u64); }
    let r = match a[2].as_str() { "locked" => scan_locked(&map), "cursor" => scan_cursor(&map), _ => 0 };
    black_box(r);
    std::mem::forget(map);
}
